#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(process.cwd());
const readJson = (rel) => JSON.parse(fs.readFileSync(path.join(ROOT, rel), 'utf8'));
const writeJson = (rel, value) => {
  fs.mkdirSync(path.dirname(path.join(ROOT, rel)), { recursive: true });
  fs.writeFileSync(path.join(ROOT, rel), JSON.stringify(value, null, 2) + '\n');
};
const writeText = (rel, value) => fs.writeFileSync(path.join(ROOT, rel), value);
const replaceSection = (text, startHeading, endHeading, replacement) => {
  const start = text.indexOf(startHeading);
  const end = text.indexOf(endHeading);
  if (start < 0 || end <= start) throw new Error(`Could not replace ${startHeading}`);
  return text.slice(0, start) + replacement + text.slice(end);
};

